    const err = dspError(code, detail);
    if (msg._iamMode === 'enforce') {
        Object.assign(msg, err);
        msg.identity = null;
        msg.iamRejected = true;
    } else {
        msg.identity = null;
        msg.iamRejected = false;
        node.warn('[iam-verify] warn-mode: ' + code + ' — ' + detail);
    }
    return msg;
}

function findJwk(doc, kid) {
    const vm = doc.verificationMethod.find(v => v.id === kid || v.id === (kid || '').split('#').pop());
    if (!vm || !vm.publicKeyJwk) throw new Error('verificationMethod not found for kid=' + kid);
    return vm.publicKeyJwk;
}

// `jose` here is in scope from this node's own `libs` declaration below.
// Each function node's sandbox is independent — libs declared on
// dsp-iam-verify-vp are NOT visible here, hence the separate declaration.

(async () => {
    const vc = msg._iamVc;
    if (!vc) {
        node.error('[iam-verify] missing _iamVc context — programmer error, check wiring');
        node.send(reject(msg, 'invalid_signature', 'internal verifier error'));
        return;
    }

    // This response came either from dsp-iam-verify-vp's cache-hit branch
    // (msg._iamVc.vcDoc already set) or from the http-request node
    // (msg.payload is the fetched did.json body) — the same
    // `didDoc || msg.payload` convention the VP stage uses, so a cache-hit's
    // carried-forward doc is never confused with an unrelated msg.payload.
    const vcDoc = vc.vcDoc || msg.payload;
    if ('_iamOrigPayload' in msg) msg.payload = msg._iamOrigPayload;
    if (!vcDoc || !Array.isArray(vcDoc.verificationMethod)) {
        node.send(reject(msg, 'key_mismatch', 'did.json unresolvable or malformed: ' + vc.vcDidUrl));
        return;
    }
    if (!vc.vcDoc) {
        const cache = global.get('iamDidCache') || new Map();
        cache.set(vc.vcDidUrl, { doc: vcDoc, fetchedAt: Date.now() });
        global.set('iamDidCache', cache);
    }

    let vcKey;
    try {
        vcKey = await jose.importJWK(findJwk(vcDoc, vc.vcHeader.kid), vc.vcHeader.alg);
    } catch (err) {
        node.send(reject(msg, 'key_mismatch', 'could not resolve VC issuer key: ' + err.message));
        return;
    }

    try {
        await jose.jwtVerify(vc.vcToken, vcKey);
    } catch (err) {
        if (err && err.code === 'ERR_JWT_EXPIRED') { node.send(reject(msg, 'token_expired', 'VC expired')); return; }
        node.send(reject(msg, 'invalid_credential', 'VC signature verification failed: ' + err.message));
        return;
    }

    const identity = {
        did: vc.holderDid,
        roles: vc.subject.roles || [],
        credentialId: vc.vcPayload.jti || vc.vcPayload.id || null,
        verifiedAt: new Date().toISOString()
    };
    delete msg._iamVc;

    // BitstringStatusList revocation check (net-new, gated by
    // DSP_STATUS_LIST_MODE=off|warn|enforce). credentialStatus is optional
    // on a VC — most VCs won't carry one, and a VC without it always skips
    // straight through here unchanged, exactly like before this check
    // existed. See dsp-iam-verify-status-list-fn for the fetch+decode.
    const statusListMode = (env.get('DSP_STATUS_LIST_MODE') || 'warn').toLowerCase();
    const credentialStatus = vc.vcPayload.vc && vc.vcPayload.vc.credentialStatus;
    if (statusListMode === 'off' || !credentialStatus || !credentialStatus.statusListCredential) {
        msg.identity = identity;
        msg.iamRejected = false;
        delete msg._iamOrigPayload;
        node.send([msg, null]);
        return;
    }

    // Function nodes have no fetch API (see this tab's own info blurb), so
    // the status list fetch is a real http-request node, same as DID
    // resolution. vcKey carries forward to verify the status list's own
    // signature without a second DID lookup — this design only
    // self-issues, so the status list and every VC it can be attached to
    // always share one issuer key.
    msg._iamStatusCheck = { credentialStatus, vcKey, identity, mode: statusListMode };
    msg.url = credentialStatus.statusListCredential;
    node.send([null, msg]);
})();
return;

function dspError(code, detail) {
    return {
        statusCode: 401,
        headers: { 'Content-Type': 'application/json', 'WWW-Authenticate': 'Bearer' },
        payload: { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': code, 'dspace:reason': [detail] }
    };
}

function rejectRevoked(msg, mode, detail) {
    delete msg._iamOrigPayload;
    const err = dspError('credential_revoked', detail);
    if (mode === 'enforce') {
        Object.assign(msg, err);
        msg.identity = null;
        msg.iamRejected = true;
    } else {
        msg.identity = null;
        msg.iamRejected = false;
        node.warn('[iam-verify] warn-mode: credential_revoked — ' + detail);
    }
    return msg;
}

// jose/zlib are in scope from this node's own libs declaration below.
// Each function node's sandbox is independent — libs declared on
// dsp-iam-verify-vc are NOT visible here.

(async () => {
    const check = msg._iamStatusCheck;
    delete msg._iamStatusCheck;
    if ('_iamOrigPayload' in msg) msg.payload = msg._iamOrigPayload;
    if (!check) {
        node.error('[iam-verify] missing _iamStatusCheck context — programmer error, check wiring');
        msg.identity = null;
        msg.iamRejected = false;
        delete msg._iamOrigPayload;
        node.send(msg);
        return;
    }

    function proceed() {
        msg.identity = check.identity;
        msg.iamRejected = false;
        delete msg._iamOrigPayload;
        node.send(msg);
    }

    // Fail-open on infra problems below (unreachable/malformed status
    // list, bad signature): this is an availability-vs-security
    // tradeoff for a control whose absence merely returns to
    // pre-status-list behaviour, not a hole in identity verification
    // itself — the VP/VC signature checks that already passed by the
    // time this node runs are entirely unaffected. Every fail-open
    // path is logged via node.warn so a persistently-unreachable
    // status list is operationally visible, not silently ignored.
    const statusListJwt = msg.payload && msg.payload.credential;
    if (!statusListJwt) {
        node.warn('[iam-verify] status list fetch returned no credential — skipping revocation check (fail-open): ' + check.credentialStatus.statusListCredential);
        return proceed();
    }

    let slPayload;
    try {
        const verified = await jose.jwtVerify(statusListJwt, check.vcKey);
        slPayload = verified.payload;
    } catch (err) {
        node.warn('[iam-verify] status list signature invalid — skipping revocation check (fail-open): ' + err.message);
        return proceed();
    }

    try {
        const encodedList = slPayload.vc && slPayload.vc.credentialSubject && slPayload.vc.credentialSubject.encodedList;
        const compressed = Buffer.from(encodedList, 'base64url');
        const bitstring = zlib.gunzipSync(compressed);
        const idx = Number(check.credentialStatus.statusListIndex);
        const byteIdx = Math.floor(idx / 8);
        const bitIdx = 7 - (idx % 8);
        const revoked = ((bitstring[byteIdx] >> bitIdx) & 1) === 1;

        if (!revoked) {
            return proceed();
        }

        node.send(rejectRevoked(msg, check.mode, 'credential ' + (check.identity.credentialId || '') + ' has been revoked'));
    } catch (err) {
        node.warn('[iam-verify] status list decode failed — skipping revocation check (fail-open): ' + err.message);
        return proceed();
    }
})();
return null;
